# projects/kg_builder.py

import spacy
from openai import OpenAI
import json

class LLMEntityExtractor:
    """Use LLM for high-quality entity and relationship extraction"""

    EXTRACTION_PROMPT = """
    Extract entities and relationships from the following text.

    Return JSON in this exact format:
    {{
        "entities": [
            {{"name": "entity name", "type": "PERSON|ORG|LOCATION|CONCEPT|PRODUCT", "description": "brief description"}}
        ],
        "relationships": [
            {{"source": "entity1", "relation": "RELATION_TYPE", "target": "entity2"}}
        ]
    }}

    Text: {text}

    Rules:
    - Use UPPERCASE_SNAKE_CASE for relation types
    - Only extract factual relationships
    - Be specific with entity names
    """

    def __init__(self, model: str = "gpt-4o-mini"):
        self.client = OpenAI()
        self.model = model

    def extract(self, text: str) -> dict:
        response = self.client.chat.completions.create(
            model=self.model,
            messages=[{
                "role": "user",
                "content": self.EXTRACTION_PROMPT.format(text=text)
            }],
            response_format={"type": "json_object"},
            temperature=0
        )
        return json.loads(response.choices[0].message.content)

class DocumentKGBuilder:
    """
    Build a Knowledge Graph from a collection of documents
    """

    def __init__(self, neo4j_connector: Neo4jGraphRAG):
        self.neo4j = neo4j_connector
        self.extractor = LLMEntityExtractor()
        self.stats = {"documents": 0, "entities": 0, "relationships": 0}

    def process_document(self, text: str, doc_id: str = None):
        """Process a single document and add to graph"""

        # Extract entities and relationships
        extracted = self.extractor.extract(text)

        # Add entities to Neo4j
        for entity in extracted.get("entities", []):
            self.neo4j.create_entity(
                name=entity["name"],
                entity_type=entity["type"],
                properties={"description": entity.get("description", "")}
            )
            self.stats["entities"] += 1

        # Add relationships to Neo4j
        for rel in extracted.get("relationships", []):
            self.neo4j.create_relationship(
                source_name=rel["source"],
                target_name=rel["target"],
                relation_type=rel["relation"]
            )
            self.stats["relationships"] += 1

        self.stats["documents"] += 1
        print(f"✅ Doc {self.stats['documents']}: "
              f"+{len(extracted.get('entities',[]))} entities, "
              f"+{len(extracted.get('relationships',[]))} relationships")

    def process_corpus(self, documents: List[str]):
        """Process multiple documents"""
        for i, doc in enumerate(documents):
            print(f"Processing document {i+1}/{len(documents)}...")
            self.process_document(doc, doc_id=f"doc_{i}")

        print(f"\n📊 Final Stats:")
        print(f"   Documents: {self.stats['documents']}")
        print(f"   Entities: {self.stats['entities']}")
        print(f"   Relationships: {self.stats['relationships']}")

# ─── USAGE ────────────────────────────────────────────────────────────
